style.css:
@-moz-document domain("discord.com") {
:root{
  --main-color: #7c4dff;
  --bg-dark: #0f1117;
  --bg-light: #1a1d29;
  --text-color: #ffffff;
  --blur: 18px;
}

body{
  background: linear-gradient(135deg,#0f1117,#1b1035) !important;
}

.appMount{
  background: transparent !important;
}

.sidebar-1tnWFu,
.chat-2ZfjoI,
.container-1eFtFS{
  background: rgba(20,20,30,0.65) !important;
  backdrop-filter: blur(var(--blur));
  border-radius: 18px;
}

.messageContent-2t3eCI{
  color: var(--text-color);
}

.button-f2h6uQ{
  background: var(--main-color) !important;
  border-radius: 14px !important;
  transition: 0.2s;
}

.button-f2h6uQ:hover{
  transform: scale(1.05);
  box-shadow: 0 0 18px var(--main-color);
}

.panels-3wFtMD{
  background: rgba(0,0,0,0.4) !important;
  backdrop-filter: blur(10px);
}
}
